def gather(root):
 groups=defaultdict(list)
 def add(owner,el,field,v):
  if not v or not re.search('[A-Za-z]',v):return
  if el.tag.endswith(('content-id','uuid')) or field=='text' and el.tag.startswith(M) and el.tag!=M+'mtext':return
  groups[owner].append((el,field,v))
 def walk(el,parent='document'):
  owner=el.get('id',parent);add(owner,el,'text',el.text);add(owner,el,'alt',el.get('alt'))
  for child in el:walk(child,owner)
  add(parent,el,'tail',el.tail)
 walk(root)
 return groups

def main():
 sys.stdout.reconfigure(encoding='utf-8')
 assert hashlib.sha256(SOURCE.read_bytes()).hexdigest()==SHA
 source=ET.parse(SOURCE).getroot();target=deepcopy(source);groups=gather(target);missing={}
 for owner,slots in groups.items():
  choices=GROUPS.get(owner)
  if choices is not None:assert len(choices)==len(slots),(owner,len(choices),len(slots))
  else:
   choices=[COMMON.get(' '.join(v.split())) for _,_,v in slots]
  if any(x is None for x in choices):
   missing[owner]=[' '.join(v.split()) for _,_,v in slots]
   continue
  for (el,field,v),new in zip(slots,choices):
   if field=='alt':el.set(field,new)
   else:setattr(el,field,re.match(r'^\s*',v).group()+new+re.search(r'\s*$',v).group())
 if missing:
  print(json.dumps({'remaining_groups':len(missing),'remaining_slots':sum(map(len,missing.values())),'missing':missing},ensure_ascii=False,indent=2))
  return
 attribute_count=apply_attributes(source,target,ATTRIBUTES_44)
 stats=validate_pair(source,target)
 target.set('{http://www.w3.org/XML/1998/namespace}lang','gu-Gujr-IN')
 output=ROOT/'gu-Gujr-IN/translations/a00-m81244.gu.cnxml'
 ET.ElementTree(target).write(output,encoding='utf-8',xml_declaration=True)
 print(json.dumps({'result':'pass',**stats,'language_slots':sum(map(len,groups.values()))+attribute_count,'accessibility_attributes':attribute_count,'sha256':hashlib.sha256(output.read_bytes()).hexdigest()},indent=2))

if __name__=='__main__':main()
